fn is_ascii_digit(c: char) -> bool {
    // Check if the character is in the range '0' to '9'
    c >= '0' && c <= '9'
}

fn all_digits(s: String) -> bool {
    // Iterate over each character in the string and verify all are ASCII digits
    // The empty string returns true (vacuously all characters are digits)
    for c in s.chars() {
        if !is_ascii_digit(c) {
            return false;
        }
    }
    true
}